async run<T>(request: ModelRequest, schema: z.ZodType<T>) {
  ScopeSchema.parse(request.scope);
  if (
    ["grading", "follow_up"].includes(request.operation) &&
    !request.attempt?.trim()
  )
    throw new GatewayError("ATTEMPT_REQUIRED", "Submit an attempt first");
  const controller = new AbortController();
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    const result = await Promise.race([
      this.provider.execute(request, controller.signal),
      new Promise<never>((_, reject) => {
        timer = setTimeout(() => {
          controller.abort();
          reject(new GatewayError("TIMEOUT", "Provider timed out"));
        }, this.timeoutMs);
      }),
    ]);
    const output = schema.safeParse(result.output);
    const metadata = MetadataSchema.safeParse(result.metadata);
    if (!output.success || !metadata.success)
      throw new GatewayError(
        "INVALID_OUTPUT",
        "Provider output failed validation",
      );
    return { output: output.data, metadata: metadata.data };
  } catch (error) {
    if (error instanceof GatewayError) throw error;
    throw new GatewayError("PROVIDER_ERROR", "Provider request failed");
  } finally {
    if (timer) clearTimeout(timer);
  }
}

export class DeterministicKeywordProvider implements ModelProvider {
  async execute(request: ModelRequest) {
    if (request.operation !== "grading")
      throw new GatewayError("UNAVAILABLE", "AI generation is not connected.");
    const answer = (request.attempt ?? "").toLocaleLowerCase();
    const terms = [
      ...new Set(request.atom.rubric.map((term) => term.toLocaleLowerCase())),
    ];
    const matches = terms.filter((term) => answer.includes(term));
    return {
      output: {
        score: matches.length / terms.length,
        confidence: null,
        feedback: `Keyword check: ${matches.length} of ${terms.length} expected terms found. Expected terms: ${request.atom.rubric.join(", ")}. This checks wording, not understanding.`,
        misconception: null,
        citations: request.atom.citations,
      },
      metadata: {
        provider: "local-keyword",
        model: "keyword-v1",
        inputTokens: 0,
        outputTokens: 0,
        estimatedCost: 0,
      },
    };
  }
}

