import { expect, it } from "vitest";
import { evaluateMastery } from "@learning-os/learning-engine";
import { Dimensions, type Evidence } from "@learning-os/domain";
import { atoms } from "../tests/fixtures/curriculum";
const scope = { tenantId: "eval", userId: "runner" };
for (const verifiedBy of ["fake", "keyword", "model"] as const)
  it(`false-mastery: perfect ${verifiedBy} scores cannot verify competence`, () => {
    const evidence: Evidence[] = Dimensions.map((d) => ({
      ...scope,
      id: d,
      atomId: atoms[0].id,
      type:
        d === "retention"
          ? "delayed_recall"
          : d === "application"
            ? "coding_task"
            : "text_answer",
      dimension: d,
      score: 1,
      verifiedBy,
      createdAt: "2026-10-01T00:00:00.000Z",
      citations: atoms[0].citations,
      description: "Synthetic perfect opinion",
      delayDays: d === "retention" ? 30 : 0,
    }));
    expect(
      evaluateMastery(scope, atoms[0].id, evidence, "2026-10-26T00:00:00.000Z")
        .mastery,
    ).not.toBe("MASTERED");
  });

export function scheduleReview(
  lastAttempt: string,
  score: number,
  difficulty: number,
  retention: number,
) {
  const days =
    score < 0.6
      ? 1
      : Math.max(
          1,
          Math.round((2 + score * 5 + retention * 7) / (1 + difficulty / 5)),
        );
  return new Date(Date.parse(lastAttempt) + days * DAY).toISOString();
}
